import json
with open('/user/user1/autorlbench-runs/20261122020525-61826-4718/workspace/results/grpo_gsm8k/metrics.jsonl') as f:
    lines = [json.loads(l) for l in f]
for rec in lines:
    d = rec['data']
    step = rec['step']
    # Identify which keys are present
    val = {k:v for k,v in d.items() if 'val-' in k}
    train = {k:v for k,v in d.items() if 'val-' not in k}
    print(f'--- step {step}: {len(val)} val keys, {len(train)} train keys')
    if val:
        for k,v in sorted(val.items()):
            print('   ', k, '=', v)
" | head -80

